begin;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create function private.valid_address(v jsonb) returns boolean language sql immutable set search_path='' as $$ select coalesce(jsonb_typeof(v)='object' and octet_length(v::text)<=2000 and v ?& array['line1','line2','city','region','postal_code','country_code'] and v->>'country_code' ~ '^$|^[A-Z]{2}$',false); $$;
create function private.valid_quote_discount(v jsonb) returns boolean language sql immutable set search_path='' as $$ select coalesce(jsonb_typeof(v)='object' and v->>'kind' in ('none','fixed','percentage') and v->>'value' ~ '^(0|[1-9][0-9]{0,11})(\.[0-9]{1,6})?$' and (v->>'kind'<>'percentage' or (v->>'value')::numeric<=100) and (v->>'kind'<>'none' or (v->>'value')::numeric=0),false); $$;
create table public.customers(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),status text not null default 'active' check(status in ('active','inactive')), customer_type text not null default 'individual' check(customer_type in ('individual','business')), display_name text not null check(length(trim(display_name)) between 1 and 200), legal_name text not null default '',phone text not null default '',secondary_phone text not null default '',email text not null default '',tax_identifier text not null default '',billing_address jsonb not null default '{"line1":"","line2":"","city":"","region":"","postal_code":"","country_code":""}'::jsonb check(private.valid_address(billing_address)),notes text not null default '' check(length(notes)<=10000));
create table public.customer_contacts(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),customer_id uuid not null, name text not null check(length(trim(name)) between 1 and 200), role text not null default '',phone text not null default '',email text not null default '',is_primary boolean not null default false, foreign key(organization_id,customer_id) references public.customers(organization_id,id));
create table public.projects(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),customer_id uuid not null, name text not null check(length(trim(name)) between 1 and 200),code text not null check(code ~ '^[A-Za-z0-9_-]{1,64}$'), industry_id uuid references public.industries(id),branch_id uuid,project_type text not null default '',site_address jsonb not null default '{"line1":"","line2":"","city":"","region":"","postal_code":"","country_code":""}'::jsonb check(private.valid_address(site_address)),status text not null default 'active' check(status in ('active','inactive')),notes text not null default '' check(length(notes)<=10000),assigned_user_id uuid, unique(organization_id,code),unique(organization_id,customer_id,id),foreign key(organization_id,customer_id) references public.customers(organization_id,id),foreign key(organization_id,branch_id) references public.branches(organization_id,id),foreign key(organization_id,assigned_user_id) references public.organization_memberships(organization_id,user_id));
create table public.project_areas(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),project_id uuid not null,parent_id uuid,name text not null check(length(trim(name)) between 1 and 200),code text not null default '',area_type text not null default '',sort_order integer not null default 0 check(sort_order between 0 and 10000),notes text not null default '' check(length(notes)<=10000),status text not null default 'active' check(status in ('active','inactive')),unique(organization_id,project_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(organization_id,project_id,parent_id) references public.project_areas(organization_id,project_id,id));
create table public.organization_quotation_settings(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),unique(organization_id),prefix text not null default 'Q' check(prefix ~ '^[A-Z][A-Z0-9-]{0,15}$'),validity_days integer not null default 30 check(validity_days between 1 and 365),default_terms text not null default '' check(length(default_terms)<=10000),default_customer_notes text not null default '' check(length(default_customer_notes)<=10000),show_quantity boolean not null default true,show_unit_rate boolean not null default true,show_specifications boolean not null default true,branding jsonb not null check(jsonb_typeof(branding)='object' and octet_length(branding::text)<=200000));
create table public.quotations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),customer_id uuid not null,project_id uuid not null,quotation_number text not null,current_revision_id uuid,next_revision integer not null default 2,status text not null default 'draft' check(status in ('draft','issued','cancelled')),unique(organization_id,quotation_number),unique(organization_id,id,project_id),foreign key(organization_id,project_id,customer_id) references public.projects(organization_id,id,customer_id));
create table public.quotation_revisions(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),quotation_id uuid not null,project_id uuid not null,revision_number integer not null check(revision_number>0),status text not null default 'draft' check(status in ('draft','issued','superseded','cancelled')),currency text not null check(currency ~ '^[A-Z]{3}$'),valid_until date not null,document_snapshot jsonb not null check(jsonb_typeof(document_snapshot)='object'),terms text not null default '',customer_notes text not null default '',internal_notes text not null default '',discount jsonb not null default '{"kind":"none","value":"0"}' check(private.valid_quote_discount(discount)),totals jsonb not null default '{"line_subtotal":"0","line_discount":"0","subtotal":"0","revision_discount":"0","final_amount":"0","optional_amount":"0"}',issued_at timestamptz,issued_by uuid references public.profiles(id),superseded_at timestamptz,cancelled_at timestamptz,created_from_revision_id uuid,unique(quotation_id,revision_number),unique(organization_id,quotation_id,id),unique(organization_id,id,project_id),foreign key(organization_id,quotation_id,project_id) references public.quotations(organization_id,id,project_id),foreign key(organization_id,quotation_id,created_from_revision_id) references public.quotation_revisions(organization_id,quotation_id,id));
create table public.quotation_items(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),revision_id uuid not null,project_id uuid not null,project_area_id uuid,catalog_item_id uuid,lineage_id uuid not null default gen_random_uuid(),optional boolean not null default false,sort_order integer not null default 0 check(sort_order between 0 and 10000),description text not null default '' check(length(description)<=3000),area_snapshot jsonb not null default '{"name":"","sort_order":0}',snapshot jsonb not null check(jsonb_typeof(snapshot)='object' and snapshot->>'snapshot_version'='1' and not(snapshot ? 'internal') and not(coalesce(snapshot->'calculation','{}') ? 'internal')),unique(revision_id,lineage_id),foreign key(organization_id,revision_id,project_id) references public.quotation_revisions(organization_id,id,project_id),foreign key(organization_id,project_id,project_area_id) references public.project_areas(organization_id,project_id,id),foreign key(organization_id,catalog_item_id) references public.catalog_items(organization_id,id));
create table public.quotation_item_costs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid not null default auth.uid() references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),item_id uuid not null unique,cost_snapshot jsonb not null check(jsonb_typeof(cost_snapshot)='object'),foreign key(organization_id,item_id) references public.quotation_items(organization_id,id));
alter table public.quotations add foreign key(organization_id,id,current_revision_id) references public.quotation_revisions(organization_id,quotation_id,id) deferrable initially deferred;
create unique index customer_primary_contact on public.customer_contacts(organization_id,customer_id) where is_primary;
create unique index quotation_one_draft on public.quotation_revisions(quotation_id) where status='draft';
create unique index quotation_one_issued on public.quotation_revisions(quotation_id) where status='issued';
create index customer_search on public.customers(organization_id,lower(display_name) text_pattern_ops,id);
create index project_search on public.projects(organization_id,lower(name) text_pattern_ops,id);
create index project_customer on public.projects(organization_id,customer_id,id);
create index quotation_search on public.quotations(organization_id,quotation_number text_pattern_ops,id);
create index quotation_status on public.quotations(organization_id,status,created_at desc,id);
create index revision_sort on public.quotation_items(organization_id,revision_id,sort_order,id);
create index areas_project_sort on public.project_areas(organization_id,project_id,sort_order,id);
create index catalog_quote_search on public.catalog_items(organization_id,lower(name) text_pattern_ops,id) where status='active';
create table private.quotation_number_sequences(organization_id uuid not null references public.organizations(id),year integer not null,last_number bigint not null default 0,primary key(organization_id,year));
create table private.quotation_signing_keys(singleton boolean primary key default true check(singleton),secret_hex text not null check(secret_hex ~ '^[0-9a-f]{64}$'));
create table private.quotation_receipts(nonce uuid primary key,actor uuid not null,expires_at timestamptz not null);
revoke all on all tables in schema private from public,anon,authenticated;
create function private.commercial_access(org uuid,permission text,capability text) returns boolean language sql stable security definer set search_path='' as $$ select private.has_permission(org,permission) and case when capability='customers' then (private.entitled(org,'quotation') or private.entitled(org,'crm')) else private.entitled(org,capability) end; $$;
alter table public.customers enable row level security;alter table public.customers force row level security;revoke all on public.customers from public,anon,authenticated;grant select on public.customers to authenticated;
create policy commercial_read on public.customers for select to authenticated using(private.commercial_access(organization_id,'customer.view','customers'));
create trigger touch_updated_at before update on public.customers for each row execute function private.touch_updated_at();
create trigger audit_mutation after insert or update on public.customers for each row execute function private.audit_mutation();
alter table public.customer_contacts enable row level security;alter table public.customer_contacts force row level security;revoke all on public.customer_contacts from public,anon,authenticated;grant select on public.customer_contacts to authenticated;
create policy commercial_read on public.customer_contacts for select to authenticated using(private.commercial_access(organization_id,'customer.view','customers'));
create trigger touch_updated_at before update on public.customer_contacts for each row execute function private.touch_updated_at();
create trigger audit_mutation after insert or update on public.customer_contacts for each row execute function private.audit_mutation();
alter table public.projects enable row level security;alter table public.projects force row level security;revoke all on public.projects from public,anon,authenticated;grant select on public.projects to authenticated;
create policy commercial_read on public.projects for select to authenticated using(private.commercial_access(organization_id,'project.view','projects'));
create trigger touch_updated_at before update on public.projects for each row execute function private.touch_updated_at();
create trigger audit_mutation after insert or update on public.projects for each row execute function private.audit_mutation();
alter table public.project_areas enable row level security;alter table public.project_areas force row level security;revoke all on public.project_areas from public,anon,authenticated;grant select on public.project_areas to authenticated;
create policy commercial_read on public.project_areas for select to authenticated using(private.commercial_access(organization_id,'project.view','projects'));
create trigger touch_updated_at before update on public.project_areas for each row execute function private.touch_updated_at();
create trigger audit_mutation after insert or update on public.project_areas for each row execute function private.audit_mutation();
alter table public.organization_quotation_settings enable row level security;alter table public.organization_quotation_settings force row level security;revoke all on public.organization_quotation_settings from public,anon,authenticated;grant select on public.organization_quotation_settings to authenticated;
create policy commercial_read on public.organization_quotation_settings for select to authenticated using(private.commercial_access(organization_id,'quotation.view','quotation'));
create trigger touch_updated_at before update on public.organization_quotation_settings for each row execute function private.touch_updated_at();
create trigger audit_mutation after insert or update on public.organization_quotation_settings for each row execute function private.audit_mutation();
alter table public.quotations enable row level security;alter table public.quotations force row level security;revoke all on public.quotations from public,anon,authenticated;grant select on public.quotations to authenticated;
create policy commercial_read on public.quotations for select to authenticated using(private.commercial_access(organization_id,'quotation.view','quotation'));
create trigger touch_updated_at before update on public.quotations for each row execute function private.touch_updated_at();
alter table public.quotation_revisions enable row level security;alter table public.quotation_revisions force row level security;revoke all on public.quotation_revisions from public,anon,authenticated;grant select on public.quotation_revisions to authenticated;
create policy commercial_read on public.quotation_revisions for select to authenticated using(private.commercial_access(organization_id,'quotation.view','quotation'));
create trigger touch_updated_at before update on public.quotation_revisions for each row execute function private.touch_updated_at();
alter table public.quotation_items enable row level security;alter table public.quotation_items force row level security;revoke all on public.quotation_items from public,anon,authenticated;grant select on public.quotation_items to authenticated;
create policy commercial_read on public.quotation_items for select to authenticated using(private.commercial_access(organization_id,'quotation.view','quotation'));
create trigger touch_updated_at before update on public.quotation_items for each row execute function private.touch_updated_at();
alter table public.quotation_item_costs enable row level security;alter table public.quotation_item_costs force row level security;revoke all on public.quotation_item_costs from public,anon,authenticated;grant select on public.quotation_item_costs to authenticated;
create policy commercial_read on public.quotation_item_costs for select to authenticated using(private.commercial_access(organization_id,'quotation.view','quotation') and private.has_permission(organization_id,'quotation.view_internal_cost'));
create trigger touch_updated_at before update on public.quotation_item_costs for each row execute function private.touch_updated_at();
revoke all on function private.valid_address(jsonb),private.valid_quote_discount(jsonb),private.commercial_access(uuid,text,text) from public,anon,authenticated;
grant execute on function private.commercial_access(uuid,text,text) to authenticated;
insert into public.permissions(id,key,scope,description) select private.seed_uuid('business-os:'||k),k,'organization',replace(k,'.',' ') from unnest(array['customer.view','customer.create','customer.manage','quotation.issue']) k on conflict(key) do nothing;
insert into private.role_template_permissions(role_key,permission_key) select r.key,p.key from private.role_templates r cross join public.permissions p where (r.key in ('owner','admin') and p.key in ('customer.view','customer.create','customer.manage','quotation.issue')) or (r.key in ('sales','branch_manager') and p.key in ('customer.view','customer.create','customer.manage','project.view','project.create','project.manage')) or (r.key in ('interior_designer','estimator','project_manager') and p.key='customer.view') on conflict do nothing;
insert into public.role_permissions(organization_id,role_id,permission_id) select r.organization_id,r.id,p.id from public.roles r join private.role_template_permissions t on t.role_key=r.key join public.permissions p on p.key=t.permission_key where p.key in ('customer.view','customer.create','customer.manage','quotation.issue') or (r.key in ('sales','branch_manager') and p.key in ('project.view','project.create','project.manage')) on conflict do nothing;
commit;
